<?php require 'config/functions.php';require 'config/database.php';$total=(int)$pdo->query('SELECT COUNT(*) FROM residents')->fetchColumn();$houses=(int)$pdo->query('SELECT COUNT(*) FROM households')->fetchColumn();$rows=$pdo->query('SELECT r.*,h.household_code FROM residents r LEFT JOIN households h ON h.id=r.household_id ORDER BY r.last_name,r.first_name')->fetchAll();start_page('Reports'); ?>
<div class="pagehead"><div class="wrap"><h1>Resident Summary Report</h1><p class="muted">Print this page or choose Save as PDF in the print dialog.</p><button class="btn primary no-print" onclick="window.print()">Print Report</button></div></div><main class="wrap"><div class="panel"><div class="grid three"><div class="card"><span class="muted">Total Residents</span><h2><?=$total?></h2></div><div class="card"><span class="muted">Total Households</span><h2><?=$houses?></h2></div><div class="card"><span class="muted">Report Date</span><h2 style="font-size:20px"><?=date('M d, Y')?></h2></div></div><h2>Resident Records</h2><div class="tablewrap"><table><thead><tr><th>Name</th><th>Address</th><th>Household</th><th>Status</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="4">No resident records available.</td></tr><?php endif;foreach($rows as $r):?><tr><td><?=e(trim($r['first_name'].' '.$r['middle_name'].' '.$r['last_name']))?></td><td><?=e($r['address'])?></td><td><?=e($r['household_code']??'Not assigned')?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></tbody></table></div></div></main><?php end_page(); ?>
